package br.com.lealinfo.vidraceiro;
import org.json.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.*;import android.util.Base64;import java.net.*;
final class PairingFlow{
 static JSONObject pdv(JSONObject data,String path)throws Exception{byte[] raw="{}".getBytes(StandardCharsets.UTF_8);PrivateKey key=KeyFactory.getInstance("EC").generatePrivate(new PKCS8EncodedKeySpec(Base64.decode(data.getString("privateKey"),Base64.DEFAULT)));String stamp=""+System.currentTimeMillis(),nonce=java.util.UUID.randomUUID().toString();Signature signer=Signature.getInstance("SHA256withECDSA");signer.initSign(key);signer.update(("POST\n"+path+"\n"+stamp+"\n"+nonce+"\n"+SecureGateway.hash(raw)).getBytes(StandardCharsets.UTF_8));HttpURLConnection c=(HttpURLConnection)new URL(SyncTransport.ORIGIN+path).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("X-Angra-Device",data.getString("deviceId"));c.setRequestProperty("X-Angra-Time",stamp);c.setRequestProperty("X-Angra-Nonce",nonce);c.setRequestProperty("X-Angra-Signature",Base64.encodeToString(signer.sign(),Base64.NO_WRAP));try(OutputStream o=c.getOutputStream()){o.write(raw);}try{if(c.getResponseCode()!=200)throw new IOException("PDV test identity failed "+c.getResponseCode());return new JSONObject(new String(SyncTransport.read(c.getInputStream(),1000000),StandardCharsets.UTF_8));}finally{c.disconnect();}}
 static void run(MeasureFlowInstrumentation t)throws Exception{MainActivity a=t.a;JSONObject data=new JSONObject(new String(Files.readAllBytes(new File(a.getFilesDir(),"pairing.json").toPath()),StandardCharsets.UTF_8));SyncTransport.register();boolean denied=false;try{SyncTransport.request("/sync/pair",new JSONObject().put("code",data.getString("oldCode")));}catch(IOException expected){denied=true;}t.check(denied,"previous code invalid after Windows renewal");
 t.ui(()->a.integration());t.set("Código de conexão mostrado no PDV",data.getString("code"));t.click("CONECTAR AO PDV");SyncFlow.waitSync(t);t.check(a.sync.state.optString("error").isEmpty(),a.sync.status());t.check(a.sync.status().contains("CONECTADO"),"native Android connected using Windows code");t.check(pdv(data,"/sync/status").getBoolean("connected"),"real gateway reports Android to Windows identity");
 t.check(a.store.list("clients").length()==0&&a.store.list("projects").length()==0,"binding only does not import operational data");pdv(data,"/sync/revoke");t.ui(()->a.sync.tick());Thread.sleep(2500);t.waitForIdleSync();t.check(a.sync.state.optBoolean("revoked"),"Android sees actual revocation");t.ui(()->a.integration());t.check(t.find(a.root,"CONECTAR AO PDV")!=null,"revoked device can enter new code without resetting app");
 String code=pdv(data,"/sync/ticket").getString("code");t.set("Código de conexão mostrado no PDV",code);t.click("CONECTAR AO PDV");SyncFlow.waitSync(t);t.check(!a.sync.state.optBoolean("revoked")&&a.sync.state.optString("error").isEmpty(),"native reconnection succeeds after revocation");t.screenshot("proof-pairing");
 }
}
